// injectMetrics.js
// This script reads an existing trace JSON, appends synthetic Lighthouse metric events,
// and writes a new trace file that you can load in chrome://tracing or DevTools > Timeline.

const fs = require('fs');
const path = require('path');

// 1. Load an existing trace (e.g. a Lighthouse / DevTools trace dump)
const TRACE_IN = path.join(__dirname, 'trace.json');
const TRACE_OUT = path.join(__dirname, 'trace-with-metrics.json');

if (!fs.existsSync(TRACE_IN)) {
  console.error(`Please put your base trace at ${TRACE_IN}`);
  process.exit(1);
}
const trace = JSON.parse(fs.readFileSync(TRACE_IN, 'utf8'));

// 2. Define your metrics (in ms from navStart)
// In a real scenario these come from Lighthouse metrics output.
const navStartMs = 0;
const metrics = [
  {name: 'First Contentful Paint',        time: 460},
  {name: 'First Meaningful Paint',       time: 1100},
  {name: 'First Visual Change',          time: 630},
  {name: 'Visually Complete',            time: 930},
  {name: 'Perceptual Speed Index',       time: 8678},
  {name: 'Time to Interactive',          time: 17400}
];

// 3. Find a pid/tid from the existing trace (we'll use the first event's pid/tid pair)
const firstEvent = trace.traceEvents[0] || {};
const pid = firstEvent.pid || 1;
const tid = firstEvent.tid || 1;

// 4. Create synthetic trace events for each metric
// We'll inject them with phase 'R' (mark events) so DevTools will draw them in the markers lane
const syntheticEvents = metrics.map((m, i) => ({
  name: m.name,
  cat: 'lighthouse',
  ph: 'R',          // 'R' = mark event, drawn as a triangle/line
  ts: (navStartMs + m.time) * 1000,  // convert ms to μs
  pid,
  tid,
  args: {label: m.name}
}));

// 5. Insert the synthetic events just before saving
trace.traceEvents = trace.traceEvents.concat(syntheticEvents);

// 6. Write out the new trace file
fs.writeFileSync(TRACE_OUT, JSON.stringify(trace, null, 2));
console.log(`Wrote injected trace to ${TRACE_OUT}`);
